from pico_ioc import component
from pico_actuator import HealthIndicator


@component
class OrderQueue:
    """The business state a load balancer would want to know about."""

    def __init__(self):
        self.depth = 0


@component
class QueueHealth(HealthIndicator):
    def __init__(self, queue: OrderQueue):
        self.queue = queue

    def check(self):
        return {
            "status": "UP" if self.queue.depth < 10 else "DOWN",
            "depth": self.queue.depth,
        }

